def parse_config(path):
    with open(path) as f:
        return Config(**yaml.safe_load(f))

fn clamp(v: f32, lo: f32, hi: f32) -> f32 {
    v.max(lo).min(hi)
}

func abs(x int) int {
    if x < 0 { return -x }
    return x
}

function toSnakeCase(s: string): string {
    return s.replace(/([A-Z])/g, '_$1').toLowerCase().replace(/^_/, '');
}

function sleep(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
}

def embed(text, key, model, dim):
    client = OpenAI(api_key=key)
    return client.embeddings.create(model=model, input=text, dimensions=dim).data[0].embedding

async function insertObservation(batchId: string, rows: ObsRow[]): Promise<void> {
    await db.query(INSERT_BATCH_SQL, [batchId, rows]);
}

func (f *Forklift) DispatchTile(tile []byte, shmName string) error {
    if err := f.shm.Write(tile); err != nil {
        return err
    }
    return f.queue.Publish(shmName)
}

async function archiveToWarehouse(obj, key) {
    await s3.putObject({ Bucket: 'warehouse-cold', Key: key, Body: obj });
}

def wait_for_clock_sync(tolerance_ms=1.0, timeout_s=30):
    deadline = time.time() + timeout_s
    while time.time() < deadline:
        offset = chrony_client.get_offset()
        if abs(offset) < tolerance_ms / 1000.0:
            return True
        time.sleep(0.1)
    return False

function passesGrammar(description) {
    const tokens = description.trim().split(/\s+/);
    if (tokens.length < 8 || tokens.length > 32) return false;
    const hedges = ['may', 'might', 'could', 'possibly', 'generally', 'typically'];
    if (hedges.some(h => description.toLowerCase().includes(h))) return false;
    const last = tokens[tokens.length - 1];
    if (last.endsWith(',') || last.endsWith(';') || last.endsWith(':')) return false;
    return true;
}

fn emit(&self, digest: &Digest) {
    let proto = digest.serialize_to_proto();
    self.redis.xadd("catwalk:digest", &[("proto", &proto)]);
}

fn collect_cpu(&self) -> Vec<Metric> {
    let pcts = read_cpu_pcts();
    pcts.iter().map(|p| Metric::new("cpu", *p)).collect()
}

async function pollManifest(url: string, etag: string): Promise<{config: Config, etag: string} | null> {
    const res = await fetch(url, { headers: { 'If-None-Match': etag } });
    if (res.status === 304) return null;
    return { config: await res.json(), etag: res.headers.get('ETag') ?? etag };
}

fn collect_memory(&self) -> Vec<Metric> {
    let info = procfs::Meminfo::new().unwrap();
    let used = info.mem_total - info.mem_free - info.buffers - info.cached;
    vec![
        Metric::new("mem_used_bytes", used as f64),
        Metric::new("mem_total_bytes", info.mem_total as f64),
    ]
}

async fn insert_batch(pool: &PgPool, batch_id: Uuid, rows: &[MetricRow]) -> Result<u64> {
    let query = build_insert_query(rows.len());
    let result = sqlx::query(&query).bind(batch_id).execute(pool).await?;
    Ok(result.rows_affected())
}

async function getDeviceStatus(req: Request, res: Response): Promise<void> {
    const device = await registry.lookup(req.params.id);
    if (!device) { res.status(404).json({ error: 'not found' }); return; }
    const status = await dispatch.query({ action: 'status', target: device.id });
    res.json({ device: device.id, ...status });
}

async function dispatchTile(tile, shmRegion) {
    await shmRegion.write(tile.data);
    await queue.publish(JSON.stringify({ handle: shmRegion.name, shape: tile.shape }));
}

def increment(self, name: str, value: float = 1.0):
    proto = Counter(name=name, value=value, timestamp=time.time()).SerializeToString()
    self.redis.xadd('catwalk:counter', {'proto': proto})

async function restartService(req: Request, res: Response): Promise<void> {
    const { service } = req.params;
    await dispatch.send({ action: 'restart', target: service });
    res.json({ status: 'ok', service });
}

