def run_mld_pipeline(func_text, budgets=[8,16,24,32], n=10):
    candidates_by_budget = {b: [generate(func_text, b) for _ in range(n)] for b in budgets}
    filtered = {b: [c for c in cs if grammar_filter(c)] for b, cs in candidates_by_budget.items()}
    vecs = {b: [embed(c) for c in filtered[b]] for b in budgets}
    converged, sv = is_converged([v for vs in vecs.values() for v in vs])
    return converged, sv

func (wg *WatchGlass) Evaluate(metrics []float64) (AnomalyVerdict, error) {
    gadf := ToGADF(metrics)
    tensor := preprocess(gadf)
    prob, err := wg.model.Infer(tensor)
    if err != nil { return AnomalyVerdict{}, err }
    return AnomalyVerdict{Score: prob, Anomalous: prob > wg.threshold}, nil
}

pub fn update_hull(&mut self, metrics: &[f64]) -> HullVerdict {
    let hull = ConvexHull::from_points(metrics);
    let z = self.z_buffer.score(&hull);
    self.history.push(hull.clone());
    HullVerdict { hull, z_score: z, healthy: z < self.threshold }
}

def run_mld_for_module(module_path, budgets=[8,16,24,32]):
    source = parse_module(module_path)
    for fn in source.functions:
        candidates = {b: [generate_candidate(fn.body, b) for _ in range(4)] for b in budgets}
        valid = {b: [c for c in cs if passes_grammar(c)] for b, cs in candidates.items()}
        best = {b: embed_centroid(valid[b]) for b in budgets if valid[b]}
        fn.mld = antipode_select(best)
    return source

func (wg *WatchGlass) Classify(window []float64) (Classification, error) {
    gadf := ComputeGADF(window)
    img := TensorFromGADF(gadf)
    logits, err := wg.model.Forward(img)
    if err != nil { return Classification{}, err }
    label, score := Argmax(logits)
    return Classification{Label: label, Score: score, Anomalous: label != "nominal"}, nil
}

func (m *Marionette) ExecuteMission(tier, block string) (*Report, error) {
    agent := m.loadAgent(tier)
    grammar := m.loadGrammar()
    result, err := m.anthropic.Messages(agent, grammar, block, m.tools)
    if err != nil { return nil, err }
    return parseReport(result), nil
}

func (c *Catwalk) EmitDetection(d Detection) error {
    proto, err := proto.Marshal(&d)
    if err != nil { return err }
    return c.redis.XAdd(ctx, &redis.XAddArgs{
        Stream: "catwalk:detection",
        Values: map[string]interface{}{"proto": proto},
    })
}

func (m *Marionette) ExecuteMission(block string, tier string) (Report, error) {
    agent := m.loadAgent(tier)
    grammar := m.loadGrammar()
    return m.claude.RunMission(agent, grammar, block)
}
